import{_ as e,c as r,o as t,a2 as i}from"./chunks/framework.CIiVzG-O.js";const f=JSON.parse('{"title":"利用規約","description":"Mac で qDiff をご利用いただくための、シンプルな規約です。","frontmatter":{"title":"利用規約","description":"Mac で qDiff をご利用いただくための、シンプルな規約です。"},"headers":[],"relativePath":"ja/terms/index.md","filePath":"ja/terms/index.md","lastUpdated":1794296122000}'),o={name:"ja/terms/index.md"};function l(n,a,d,p,h,c){return t(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="利用規約" tabindex="-1">利用規約 <a class="header-anchor" href="#利用規約" aria-label="Permalink to &quot;利用規約&quot;">​</a></h1><p><em>最終更新日: 2026年11月6日</em></p><p>qDiff をご利用いただき、ありがとうございます。本規約はアプリとこのウェブサイトに 適用されます。</p><h2 id="アプリのご利用について" tabindex="-1">アプリのご利用について <a class="header-anchor" href="#アプリのご利用について" aria-label="Permalink to &quot;アプリのご利用について&quot;">​</a></h2><p>qDiff は、ご自身のファイルを比較・整理するためのものです。ご家庭でも職場でも ご利用いただけます。開くファイルを選ぶ責任、および大切なデータのバックアップを 保つ責任は、お客様にあります。</p><p>アプリは「現状のまま」提供されます。信頼性のために努めていますが、中断や エラーが一切ないことをお約束することはできず、データの消失について責任を 負いかねます。ファイルの同期や削除の前には、必ずバックアップをお取りください。</p><h2 id="無料版と購入" tabindex="-1">無料版と購入 <a class="header-anchor" href="#無料版と購入" aria-label="Permalink to &quot;無料版と購入&quot;">​</a></h2><p>すべての比較機能は無料です。無料版ではタブバーに小さなマークが表示されます。 一度きりの非消耗型の購入でこのマークが消え、今後追加されるプレミアム機能も 含まれます。サブスクリプションはありません。</p><p>購入、返金、復元は Apple の規約とお使いの Apple ID のもと、Mac App Store で 処理されます。私たちがお支払い情報を受け取ることはありません。</p><h2 id="お客様のコンテンツ" tabindex="-1">お客様のコンテンツ <a class="header-anchor" href="#お客様のコンテンツ" aria-label="Permalink to &quot;お客様のコンテンツ&quot;">​</a></h2><p>私たちはお客様のファイルに対していかなる権利も主張せず、ファイルを受け取る こともありません。詳しくは<a href="./../privacy/">プライバシーポリシー</a>をご覧ください。</p><h2 id="このウェブサイトについて" tabindex="-1">このウェブサイトについて <a class="header-anchor" href="#このウェブサイトについて" aria-label="Permalink to &quot;このウェブサイトについて&quot;">​</a></h2><p>このサイトのコンテンツは情報提供のみを目的としています。qDiff の改善に伴い、 製品の説明は更新される場合があります。</p><h2 id="変更について" tabindex="-1">変更について <a class="header-anchor" href="#変更について" aria-label="Permalink to &quot;変更について&quot;">​</a></h2><p>本規約を更新する場合があり、その際は上記の日付が変わります。更新後も qDiff のご利用を続けられた場合、改訂後の規約に同意されたものとみなされます。</p><h2 id="お問い合わせ" tabindex="-1">お問い合わせ <a class="header-anchor" href="#お問い合わせ" aria-label="Permalink to &quot;お問い合わせ&quot;">​</a></h2><p>ご質問は <a href="mailto:qdiff@w3cub.com" target="_blank" rel="noreferrer">qdiff@w3cub.com</a> までご連絡ください。</p>',17)])])}const m=e(o,[["render",l]]);export{f as __pageData,m as default};
